import{z as l,x as s,o as B,c as d,q as r,j as n,D as a,d as e,s as o,S as i,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"因子构造的方法论","description":"","frontmatter":{"title":"因子构造的方法论","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fz-construction-method.md","filePath":"quant/fz-construction-method.md","lastUpdated":1791413859000}'),p={name:"quant/fz-construction-method.md"};function m(D,E,h,c,u,F){const A=s("Mermaid");return B(),d("div",null,[E[2]||(E[2]=r('<h1 id="因子构造的方法论" tabindex="-1">因子构造的方法论 <a class="header-anchor" href="#因子构造的方法论" aria-label="Permalink to &quot;因子构造的方法论&quot;">​</a></h1><div class="epigraph"><p>因子不是从数据里「发现」的，而是被一整套排序、加权与再平衡的约定「制造」出来的；同一个思想，两种构造，可以给出两个不同的溢价。</p><footer>—— 据 Fama &amp; French, Journal of Financial Economics, 1993；Carhart, Journal of Finance, 1997 的构造约定整理</footer></div><p><a href="/quant/ex-case-map">上一课</a>把交易执行深钻收束：算法谱系、暗池与竞价、TCA 的陷阱、成本预测与最优转换，最终归档成案例集——执行侧回答的是「怎样把目标仓位换成成交」。缺口在上游：仓位背后的研究对象从哪来。本课是「因子研究深化」的第一课，把因子构造的约定一次钉死：投资域、排序方式、加权与再平衡。后面十一课默认你已掌握这套词汇；构造的完整参数清单，也是本课程报告规范课与复现练习课的接口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>「便宜的股票跑赢」是一个思想；落成数字要经过一串自由度：在哪个域里选股、用什么口径定义便宜、切几档、两端怎么加权、多久再平衡。每个自由度都移动溢价估计。麻烦不在于数字会变，而在于不同自由度混入的「额外收益」不同：等权加月度再平衡的组合隐含「卖涨买跌」的反转操作，市值加权的组合没有；独立双重排序的两端格数不均，会把规模暴露漏进所谓「纯价值」。构造不透明，后续的正交化、拥挤、衰减都没有共同基准；因子动物园里的争吵，一大半是两套约定的争吵。</p><p><span class="marginnote">直觉类比：因子构造约定就像同一道菜的火候与克数——「便宜的股票跑赢」是菜名，域、切档、加权、调仓频率是配方细节。换了配方，「同一个菜」端上来味道（溢价）可以差出一半；两篇论文吵价值因子死没死，常常只是配方不同。</span></p><h3 id="三层自由度" tabindex="-1">三层自由度 <a class="header-anchor" href="#三层自由度" aria-label="Permalink to &quot;三层自由度&quot;">​</a></h3><p>第一层，域与数据：可投资域的流动性下限、退市与停牌处理、特征的 point-in-time 可得性（见<a href="/quant/no-future-function">无未来函数</a>）。第二层，排序：单变量十分位，或双重排序；独立排序（先全市场按规模切，再各自独立按 B/M 切）与条件排序（先切规模，再在每组内切 B/M）答案不同。第三层，加权与再平衡：等权、市值加权、特征加权；持有期与调仓频率。三层全部写下来，构造才算被定义。</p><p><span class="marginnote">独立双重排序会产生空格与两端失衡：按市值与 B/M 各切三档后，超小盘的高 B/M 格可能只剩几只票，多空两端的市值分布也偏。条件排序保证每格有样本，但结果依赖「先按哪个变量切」——两种都是合法构造，报告必须写明是哪一种。</span></p><p><span class="marginnote">数字实例：Fama–French 1993 的经典配方是「NYSE 中位数切规模、30%/70% 分位切 B/M」，得到 \\(2\\times3=6\\) 个市值加权组合；SMB = 三个小盘组合的均值减三个大盘组合的均值，HML = 两个高 B/M 减两个低 B/M。每个参数（NYSE 分位而非全市场、6 月末而非月末重构）都是声明过的选择。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把构造写成一句可执行的话：因子收益是权重向量的时间序列 \\(f_t=w_t^\\top R_t\\)，而 \\(w_t\\) 由排序规则从特征生成。方法论就是对生成 \\(w_t\\) 的每一处自由度给出显式声明。Fama–French 1993 的示范是：用 NYSE 分位点把市值切两档、B/M 切三档，构成六个市值加权组合，每年 6 月末重构一次，SMB 与 HML 是这六个组合的线性组合。Carhart 1997 把动量以同样的语言接入：按过去 12 个月（跳过最近 1 个月）收益排序，多空两端构成 WML，月度重构。两条构造被文献复用三十年，正因参数被完整写死。</p><p>产出有两个，同等重要：收益序列 \\(f_t\\) 与每期多空持仓清单。后者是正交化、拥挤度量与暴露检查的原料；只交收益序列，后半程研究全被堵死。</p>',13)),(B(),n(i,null,{default:a(()=>[o(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E7%89%B9%E5%BE%81%E4%B8%8E%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20PIT%5B%22%E5%9F%9F%E8%BF%87%E6%BB%A4%E4%B8%8E%20point-in-time%20%E6%A3%80%E6%9F%A5%22%5D%0A%20%20PIT%20--%3E%20SORT%5B%22%E6%8E%92%E5%BA%8F%E5%88%86%E7%BB%84%EF%BC%9A%E5%8D%95%E5%8F%98%E9%87%8F%E6%88%96%E5%8F%8C%E9%87%8D%22%5D%0A%20%20SORT%20--%3E%20W%5B%22%E4%B8%A4%E7%AB%AF%E5%8A%A0%E6%9D%83%EF%BC%9A%E7%AD%89%E6%9D%83%2F%E5%B8%82%E5%80%BC%2F%E7%89%B9%E5%BE%81%E5%8A%A0%E6%9D%83%22%5D%0A%20%20W%20--%3E%20REB%5B%22%E5%86%8D%E5%B9%B3%E8%A1%A1%EF%BC%9A%E9%A2%91%E7%8E%87%E4%B8%8E%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%0A%20%20REB%20--%3E%20F%5B%22%E5%9B%A0%E5%AD%90%E6%94%B6%E7%9B%8A%E5%BA%8F%E5%88%97%22%5D%0A%20%20REB%20--%3E%20H%5B%22%E5%A4%9A%E7%A9%BA%E6%8C%81%E4%BB%93%E6%B8%85%E5%8D%95%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[e("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,"为什么这些约定不是「实现细节」？因为每一处都在改变 \\(w_t\\) 与价格的互动方式。等权月度调仓的 \\(w_t\\) 每月向初始权重回归，机械地做空近期上涨者——它把短期反转溢价计入了因子收益，这部分收益不来自「便宜」，来自调仓动作本身。市值加权不再平衡，权重随价格漂移，没有这种红利；等权溢价系统性高于市值加权的部分，是再平衡红利而非特征溢价。识别的方法是问：这笔收益要求我做什么交易？月度等权每月换手，成本后溢价缩水多少就是红利的上界。同样的追问适用于每一层自由度。",-1)),(B(),n(i,null,{default:a(()=>[o(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E6%9C%88%E5%88%9D%3A%20%E5%A4%9A%E7%A9%BA%E4%B8%A4%E7%AB%AF%E7%AD%89%E6%9D%83%E5%BB%BA%E4%BB%93%22%5D%20--%3E%20M%5B%22%E6%9C%88%E4%B8%AD%E4%BB%B7%E6%A0%BC%E5%8F%98%E5%8A%A8%3A%3Cbr%2F%3E%E8%B5%A2%E5%AE%B6%E6%B6%A8%E3%80%81%E8%BE%93%E5%AE%B6%E8%B7%8C%22%5D%0A%20%20M%20--%3E%20D%5B%22%E6%9D%83%E9%87%8D%E6%BC%82%E7%A7%BB%3A%3Cbr%2F%3E%E8%B5%A2%E5%AE%B6%E5%8D%A0%E6%AF%94%E8%B6%85%E8%BF%87%2050%25%22%5D%0A%20%20D%20--%3E%20T1%5B%22%E6%9C%88%E6%9C%AB%E5%86%8D%E5%B9%B3%E8%A1%A1%3A%3Cbr%2F%3E%E5%8D%96%E8%B5%A2%E4%B9%B0%E8%BE%93%E5%9B%9E%E5%88%B0%E7%AD%89%E6%9D%83%22%5D%0A%20%20T1%20--%3E%20RB%5B%22%E6%9C%BA%E6%A2%B0%E9%AB%98%E6%8A%9B%E4%BD%8E%E5%90%B8%3A%3Cbr%2F%3E%E5%86%8D%E5%B9%B3%E8%A1%A1%E7%BA%A2%E5%88%A9%22%5D%0A%20%20RB%20--%3E%20Q%5B%22%E5%9B%A0%E5%AD%90%E6%94%B6%E7%9B%8A%20%3D%20%E7%89%B9%E5%BE%81%E6%BA%A2%E4%BB%B7%20%2B%20%E8%B0%83%E4%BB%93%E7%BA%A2%E5%88%A9%22%5D%0A%20%20Q%20--%3E%20Q1%5B%22%E4%B8%8D%E6%8B%86%E5%BC%80%3A%20%E6%BA%A2%E4%BB%B7%E8%A2%AB%E9%AB%98%E4%BC%B0%22%5D%0A%20%20Q%20--%3E%20Q2%5B%22%E6%89%A3%E6%8E%89%E6%8D%A2%E6%89%8B%E6%88%90%E6%9C%AC%3A%3Cbr%2F%3E%E7%BA%A2%E5%88%A9%E4%B8%8A%E7%95%8C%E7%8E%B0%E5%BD%A2%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">常见误区：初学者容易把「等权因子溢价更高」解读为「这个特征更有效」，实际上多出的部分是每月卖涨买跌的反转红利——是调仓动作赚的，不是「便宜」赚的。检验办法：把调仓频率降到年度，若溢价大幅缩水，缩掉的就是红利加成本。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课只定义构造，不做评估：单因子怎么打分见<a href="/quant/single-signal-eval">单信号评估</a>，特征回归与 β 回归的区分见 <a href="/quant/fama-macbeth">Fama–MacBeth</a>。构造层面的中性化（行业、规模残差化）留给下一课的正交化；组合层面的暴露控制是本课程后段的主题。因子择时与容量不是构造问题，后面各有专课。还有一个诚实的提醒：构造自由度本身就是多重检验的入口——「换一种切法显著了」不是新发现，试了多少次切法要记下来。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>因子是被约定制造的：域、排序、加权、再平衡四类自由度必须显式声明，否则不可复现。</li><li>等权与月度调仓混入反转与再平衡红利；市值加权是更保守的默认。</li><li>独立与条件双重排序答案不同，两端失衡会把规模暴露漏进因子。</li><li>产出是收益序列加持仓清单，两者缺一不可。</li><li>出处：Fama &amp; French, <em>JFE</em>, 1993；Carhart, <em>JF</em>, 1997；构造细节据原文构造节整理。</li></ul>',5))])}const _=l(p,[["render",m]]);export{C as __pageData,_ as default};
